<script setup>
import { computed, onMounted, ref } from 'vue'
import { ChevronRight, CirclePercent, Home, ReceiptText, RefreshCcw, Store, UserRound } from 'lucide-vue-next'
const ShoppingBasket = Store; const Percent = CirclePercent; const Package = ReceiptText
import { useRoute, useRouter } from 'vue-router'
import { useSessionStore } from '../stores/session'
import { listClientOrders } from '../services/clientOrderService'
import '../assets/client-orders.css'
import '../assets/client-orders-reference.css'
const session = useSessionStore(); const router = useRouter(); const route = useRoute(); const orders = ref([]); const filter = ref('EN_CURSO'); const loading = ref(true); const error = ref('')
const activeStates = ['PENDIENTE_ACEPTACION', 'PREPARANDO', 'LISTO_PARA_RECOGER', 'PENDIENTE', 'ASIGNADO', 'RECOGIDO', 'EN_CAMINO']
const visibleOrders = computed(() => orders.value.filter((item) => filter.value === 'CANCELADO' ? item.estado === 'CANCELADO' : filter.value === 'ENTREGADO' ? item.estado === 'ENTREGADO' : activeStates.includes(item.estado)))
const groupedOrders = computed(() => { const groups = new Map(); visibleOrders.value.forEach((order) => { const date = new Date(order.created_at); const key = `${date.getFullYear()}-${date.getMonth()}`; if (!groups.has(key)) groups.set(key, { label: date.toLocaleDateString('es-SV', { month: 'long' }), items: [] }); groups.get(key).items.push(order) }); return [...groups.values()] })
function dateLabel(order) { return new Date(order.created_at).toLocaleDateString('es-SV', { weekday: 'short', day: '2-digit', month: '2-digit' }) }
function statusLabel(order) { const labels = { PENDIENTE_ACEPTACION: 'Pendiente de aprobación', PREPARANDO: 'En preparación', LISTO_PARA_RECOGER: 'Listo para recoger', PENDIENTE: 'Pendiente', ASIGNADO: 'Repartidor asignado', RECOGIDO: 'Recogido', EN_CAMINO: 'En camino', CANCELADO: 'Cancelado', ENTREGADO: 'Entregado' }; return labels[order.estado] || order.estado }
function refundLabel(order) { if (order.estado_pago === 'CANCELADO_SIN_COBRO') return 'Sin cobro'; const status = order.reembolsos?.[0]?.estado; return { SIMULADO_PENDIENTE: 'Devolución pendiente', SIMULADO_COMPLETADO: 'Devolución completada', REVISION_MANUAL: 'Devolución en revisión', REVISION_APROBADA: 'Devolución aprobada', REVISION_RECHAZADA: 'Devolución rechazada' }[status] || (order.estado === 'CANCELADO' ? 'Sin devolución registrada' : '') }
function open(order) { router.push({ name: 'order-confirmation', params: { id: order.id } }) }
async function load() { try { orders.value = await listClientOrders(session.user.id) } catch (e) { error.value = e.message || 'No se pudieron cargar tus pedidos.' } finally { loading.value = false } }
onMounted(load)
</script>
<template><main class="client-orders-page"><header class="client-orders-header"><h1>Mis pedidos</h1><button aria-label="Ir al carrito" @click="router.push('/carrito')"><ShoppingBasket :size="30" /></button></header><section class="client-orders-content"><div class="client-order-tabs"><button :class="{ active: filter === 'ENTREGADO' }" @click="filter = 'ENTREGADO'">Entregados</button><button :class="{ active: filter === 'CANCELADO' }" @click="filter = 'CANCELADO'">Cancelados</button></div><div v-if="loading" class="client-orders-empty">Cargando tus pedidos…</div><div v-else-if="error" class="client-orders-empty client-orders-error">{{ error }}<button @click="load">Reintentar</button></div><div v-else-if="!groupedOrders.length" class="client-orders-empty"><Package :size="42" /><h2>{{ filter === 'CANCELADO' ? 'No tienes pedidos cancelados' : 'Aún no tienes pedidos entregados' }}</h2><p>Tus pedidos aparecerán aquí cuando se actualicen.</p></div><section v-else v-for="group in groupedOrders" :key="group.label" class="client-orders-month"><h2>{{ group.label }}</h2><article v-for="order in group.items" :key="order.id" class="client-order-card" @click="open(order)"><img class="client-order-restaurant-image" :src="order.restaurantes?.imagen_url || order.pedido_detalles?.[0]?.productos?.imagen_url || '/logos/logo.png'" :alt="order.restaurantes?.nombre || 'Restaurante'" /><div class="client-order-main"><span class="client-order-kicker">Cerrado por hoy</span><div class="client-order-status"><strong>{{ statusLabel(order) }}</strong><span>{{ dateLabel(order) }}</span></div><small v-if="filter === 'CANCELADO'" class="client-refund-status">{{ refundLabel(order) }}</small><h3>{{ order.restaurantes?.nombre || 'Restaurante' }} <span v-if="order.direcciones?.zonas?.nombre">– {{ order.direcciones.zonas.nombre }}</span></h3><div class="client-order-products"><img v-for="line in order.pedido_detalles?.slice(0, 3)" :key="line.id" :src="line.productos?.imagen_url || '/logos/logo.png'" :alt="line.nombre_producto_snapshot" /><span v-if="(order.pedido_detalles?.length || 0) > 3">+{{ order.pedido_detalles.length - 3 }}</span></div></div><strong class="client-order-total">${{ Number(order.total).toFixed(2) }}</strong><ChevronRight class="client-order-chevron" :size="18" /></article><button v-for="order in group.items" :key="`repeat-${order.id}`" class="client-repeat-button" disabled><RefreshCcw :size="20" /> Repetir</button></section></section><nav class="bottom-nav client-orders-nav"><RouterLink class="bottom-nav__item" :class="{ 'is-active': route.path === '/' }" to="/"><Home :size="23" /><span>Inicio</span></RouterLink><RouterLink class="bottom-nav__item" to="/restaurantes"><ShoppingBasket :size="23" /><span>Mercados</span></RouterLink><a class="bottom-nav__item" href="#"><Percent :size="23" /><span>Promociones</span></a><RouterLink class="bottom-nav__item is-active" to="/cliente"><Package :size="23" fill="currentColor" /><span>Pedidos</span></RouterLink><RouterLink class="bottom-nav__item" to="/perfil"><UserRound :size="23" /><span>Mi perfil</span></RouterLink></nav></main></template>
